const { DateTime, Duration, Interval, Settings } = require("/luxon/src/luxon.js");
const assert = require("assert");

function check(name, fn) {
  try {
    fn();
    console.log("PASS:", name);
  } catch (err) {
    console.log("FAIL:", name, "->", err && err.message);
    process.exitCode = 1;
  }
}

// 1. date/duration form with throwOnInvalid = true
check("date/duration with throwOnInvalid=true", () => {
  Settings.throwOnInvalid = true;
  const i = Interval.fromISO("2020-06-22T17:30:00.000+02:00/PT5H30M");
  assert.strictEqual(i.isValid, true, "should be valid");
  assert.strictEqual(i.start.toISO(), "2020-06-22T17:30:00.000+02:00");
  assert.strictEqual(i.end.toISO(), "2020-06-22T23:00:00.000+02:00");
  assert.strictEqual(i.start.plus({ hours: 5, minutes: 30 }).toISO(), i.end.toISO());

  Settings.throwOnInvalid = false;
  const ref = Interval.fromISO("2020-06-22T17:30:00.000+02:00/PT5H30M");
  assert.strictEqual(i.equals(ref), true, "should equal throwOnInvalid=false result");
  assert.strictEqual(i.toISO(), ref.toISO());
});

// 2. reversed duration/date form
check("duration/date with throwOnInvalid=true", () => {
  Settings.throwOnInvalid = true;
  const i = Interval.fromISO("PT5H30M/2020-06-22T17:30:00.000+02:00");
  assert.strictEqual(i.isValid, true, "should be valid");
  assert.strictEqual(i.start.toISO(), "2020-06-22T12:00:00.000+02:00");
  assert.strictEqual(i.end.toISO(), "2020-06-22T17:30:00.000+02:00");

  Settings.throwOnInvalid = false;
  const ref = Interval.fromISO("PT5H30M/2020-06-22T17:30:00.000+02:00");
  assert.strictEqual(i.equals(ref), true, "should equal throwOnInvalid=false result");
});

// 3. plain date/date with zone option
check("date/date with zone option", () => {
  Settings.throwOnInvalid = true;
  const i = Interval.fromISO("2016-01-01/2016-12-31", { zone: "Europe/Paris" });
  assert.strictEqual(i.isValid, true);
  assert.strictEqual(i.start.zoneName, "Europe/Paris");
  assert.strictEqual(i.end.zoneName, "Europe/Paris");
});

// 4. date/duration P1Y2M10DT2H30M
check("2007-03-01T13:00:00/P1Y2M10DT2H30M", () => {
  Settings.throwOnInvalid = true;
  const i = Interval.fromISO("2007-03-01T13:00:00/P1Y2M10DT2H30M");
  assert.strictEqual(i.isValid, true);
  assert.strictEqual(i.end.toISO(), "2008-05-11T15:30:00.000+00:00");
  assert.strictEqual(i.end.toISO().slice(0, 19), "2008-05-11T15:30:00");
});

// 5. unparsable still throws with throwOnInvalid = true
check("foo/bar throws InvalidIntervalError with throwOnInvalid=true", () => {
  Settings.throwOnInvalid = true;
  let threw = null;
  try {
    Interval.fromISO("foo/bar");
  } catch (err) {
    threw = err;
  }
  assert.ok(threw, "expected a throw");
  assert.strictEqual(threw.name, "InvalidIntervalError", "expected InvalidIntervalError, got " + threw.name);
  console.log("   (threw " + threw.name + ": " + threw.message + ")");
});

// 6. unparsable returns invalid interval with throwOnInvalid = false
check("foo/bar returns invalid interval with throwOnInvalid=false", () => {
  Settings.throwOnInvalid = false;
  const i = Interval.fromISO("foo/bar");
  assert.strictEqual(i.isValid, false);
  assert.strictEqual(i.invalidReason, "unparsable");
});

// extra: single-half and non-string inputs should not blow up
check("edge cases", () => {
  Settings.throwOnInvalid = false;
  assert.strictEqual(Interval.fromISO("2020-01-01").isValid, false);
  assert.strictEqual(Interval.fromISO("").isValid, false);
  assert.strictEqual(Interval.fromISO(undefined).isValid, false);
  assert.strictEqual(Interval.fromISO("PT5H30M/PT1H").isValid, false);
});

Settings.throwOnInvalid = false;
console.log("done");
EOF
